import re, math, numpy as np
from typing import List, Dict

def _shape_desc(desc: str) -> str:
    m = re.search(r"shape=([a-zA-Z]+)", desc)
    return m.group(1) if m else ""

def _friction_from_records(doc: Dict) -> float:
    fric = []
    prev = {}
    for n in doc.get("nodes", []):
        if n.get("kind") != "table" or not n.get("title", "").endswith("Motion log"):
            continue
        for row in n.get("table", {}).get("rows", []):
            try:
                obj = "Object " + row[1].split()[0]
                spd = float(row[6])
            except Exception:
                continue
            if obj in prev:
                old = prev[obj]
                if old > 0.1 and spd < old:
                    fric.append(1 - spd / old)
            prev[obj] = spd
    return sorted(fric)[len(fric)//2] if fric else 0.05

def _radii_from_collisions(doc: Dict) -> Dict[str, float]:
    pos = {}
    for n in doc.get("nodes", []):
        if n.get("kind") != "table" or not n.get("title", "").endswith("Motion log"):
            continue
        sc = n["title"].split(":")[0]
        for row in n.get("table", {}).get("rows", []):
            try:
                f = int(row[0]); obj = "Object " + row[1].split()[0]; x, y = float(row[2]), float(row[3])
            except Exception:
                continue
            pos[(sc, f, obj)] = (x, y)
    dist = {}
    for n in doc.get("nodes", []):
        if n.get("kind") != "list" or not n.get("title", "").endswith("Events"):
            continue
        sc = n["title"].split(":")[0]
        for line in n.get("lines", []):
            if not re.search(r"\bcollide\b|\bcollision\b", line, re.I):
                continue
            f = int(line.split(":")[0].split()[1])
            objs = [f"Object {m}" for m in re.findall(r"Object (\d+)", line)]
            if len(objs) < 2: continue
            p1 = pos.get((sc, f, objs[0]))
            p2 = pos.get((sc, f, objs[1]))
            if not p1 or not p2: continue
            d = math.hypot(p1[0]-p2[0], p1[1]-p2[1])
            for oid in objs:
                shape = None
                for e in entities(doc, sc):
                    if e["id"] == oid:
                        shape = _shape_desc(e["description"])
                        break
                if shape:
                    dist.setdefault(shape, []).append(d/2)
    radii = {s: sum(v)/len(v) for s, v in dist.items()}
    return radii

def simulate_local(doc, scope, removed=(), horizon=None, start=0.0):
    f = _friction_from_records(doc)
    radii = _radii_from_collisions(doc)
    if horizon is None:
        horizon = recorded_end(doc, scope)

    # Prepare entity data
    all_objs = entities(doc, scope)
    all_objs = [o for o in all_objs if o["id"] not in removed]
    shape_map = {o["id"]: _shape_desc(o["description"]) for o in all_objs}

    # Read motion records
    motion = node_by_title(doc, f"{scope}: Motion log")
    recs = {}
    if motion:
        for row in motion.get("table", {}).get("rows", []):
            try:
                fid = int(row[0]); oid = "Object " + row[1].split()[0]
            except Exception:
                continue
            if oid in removed: continue
            recs.setdefault(oid, []).append({
                "frame": fid,
                "x": float(row[2]),
                "y": float(row[3]),
                "vx": float(row[4]),
                "vy": float(row[5]),
            })
    for l in recs.values(): l.sort(key=lambda r: r["frame"])

    state = {}
    upcoming = {}
    for oid, lst in recs.items():
        if not lst: continue
        if lst[0]["frame"] <= start:
            # last record before start
            last = lst[0]
            for r in lst:
                if r["frame"] > start: break
                last = r
            state[oid] = {"pos": [last["x"], last["y"]], "vel": [last["vx"], last["vy"]]}
        else:
            upcoming[oid] = lst[0]["frame"]

    events = []
    t = math.floor(start)
    while t <= math.ceil(horizon):
        # Add new objects
        for oid in list(upcoming):
            if upcoming[oid] == t:
                first = recs[oid][0]
                state[oid] = {"pos": [first["x"], first["y"]], "vel": [first["vx"], first["vy"]]}
                del upcoming[oid]
        # Move
        for st in state.values():
            st["pos"][0] += st["vel"][0]
            st["pos"][1] += st["vel"][1]
        # Collisions
        ids = list(state.keys())
        for i in range(len(ids)):
            for j in range(i+1, len(ids)):
                o1, o2 = ids[i], ids[j]
                p1, p2 = state[o1]["pos"], state[o2]["pos"]
                dx, dy = p1[0]-p2[0], p1[1]-p2[1]
                d2 = dx*dx + dy*dy
                rsum = radii.get(shape_map[o1], 0.3) + radii.get(shape_map[o2], 0.3) + 1e-8
                if d2 <= rsum*rsum:
                    if t > start:
                        events.append({"time": float(t), "kind":"collision", "participants":[o1, o2]})
                    # equal‑mass elastic
                    v1, v2 = state[o1]["vel"], state[o2]["vel"]
                    dist = math.sqrt(d2) + 1e-12
                    nx, ny = dx/dist, dy/dist
                    rvx, rvy = v1[0]-v2[0], v1[1]-v2[1]
                    reln = rvx*nx + rvy*ny
                    if reln:
                        v1[0] -= reln*nx
                        v1[1] -= reln*ny
                        v2[0] += reln*nx
                        v2[1] += reln*ny
        # Friction
        for st in state.values():
            st["vel"][0] *= (1-f)
            st["vel"][1] *= (1-f)
            if math.hypot(*st["vel"]) < 0.1:
                st["vel"] = [0.0,0.0]
        t += 1

    return [e for e in events if e["time"] > start]

